// Posters and validation are generated by default; pass --video to also export MP4.
import fs from 'node:fs/promises';import path from 'node:path';import {fileURLToPath,pathToFileURL} from 'node:url';import {spawn} from 'node:child_process';import {once} from 'node:events';import assert from 'node:assert/strict';import sharp from 'sharp';
const dir=path.dirname(fileURLToPath(import.meta.url)),bundle=path.resolve(process.argv[2]),temp=path.join(dir,'temp/image-clip'),out=path.resolve(dir,'../IMAGE/07-SW-Overview');
const trace=JSON.parse(await fs.readFile(path.join(dir,'image-clip-trace.txt'),'utf8')),variant=JSON.parse(await fs.readFile(path.join(dir,'image-clip-variant.txt'),'utf8'));
const source=await fs.readFile(path.join(dir,'sw-image-clip-tasks.lua'),'utf8');
const lua=v=>Array.isArray(v)?'{'+v.map(lua).join(',')+'}':v&&typeof v==='object'?'{'+Object.entries(v).map(([k,v])=>`${k}=${lua(v)}`).join(',')+'}':JSON.stringify(v);
assert(source.includes('local trace='+lua(trace)));
const {createTMath}=await import(pathToFileURL(path.join(bundle,'client.js')));const runtime=await createTMath('return tmath.scene{theme="pro_white"}','bootstrap.lua',{renderEngine:'cpu',wasmBinary:await fs.readFile(path.join(bundle,'tmath-wasm.wasm'))});runtime.font('Pretendard',await fs.readFile(path.join(bundle,'Pretendard.ttf')));
const rgb=v=>[v&255,(v>>>8)&255,(v>>>16)&255];let checks=0;
const pixel=(b,w,x,y)=>[...b.subarray((Math.floor(y)*w+Math.floor(x))*4,(Math.floor(y)*w+Math.floor(x))*4+3)];
const eq=(a,b,id)=>{assert(a.every((v,i)=>Math.abs(v-b[i])<=1),`${id}: ${a}/${b}`);checks++;};
try{
 runtime.loadLua(source,'sw-image-clip-tasks.lua');const [width,height]=runtime.size(),duration=runtime.duration,frames=Math.ceil(duration*30)+1;
 let margin=Infinity;const labels=new Set();
 for(let f=0;f<frames;f++){
  const objects=runtime.layoutReport(Math.min(f/30,duration),4).objects,texts=[];
  for(const o of objects){if(o.type==='text')assert(o.id.startsWith('label_'));if(!o.visible||o.type==='group')continue;const b=o.paintBounds;assert(b&&b.width>0&&b.height>0);const m=Math.min(b.x,b.y,width-b.x-b.width,height-b.y-b.height);margin=Math.min(margin,m);assert(m>=4,'overflow '+o.id);if(o.type==='text'){texts.push(o);labels.add(o.id);}}
  for(let i=0;i<texts.length;i++)for(let j=i+1;j<texts.length;j++){const a=texts[i].paintBounds,b=texts[j].paintBounds;assert(Math.max(a.x-b.x-b.width,b.x-a.x-a.width)>=4||Math.max(a.y-b.y-b.height,b.y-a.y-a.height)>=4,`text overlap ${texts[i].id}/${texts[j].id}`);}
 }
 let memory=new Array(trace.stride*trace.h).fill(trace.background);
 const check=(time,name)=>{const b=Buffer.from(runtime.render(time,true));for(let y=0;y<trace.h;y++)for(let x=0;x<trace.w;x++){
  eq(pixel(b,width,1670+(x+.5)*44,220+(y+.5)*44),rgb(memory[y*trace.stride+x]),name);
  if(x>=trace.tx&&x<trace.tx+trace.iw&&y>=trace.ty&&y<trace.ty+trace.ih)eq(pixel(b,width,900+(x+.5)*44,220+(y+.5)*44),rgb(trace.source[(y-trace.ty)*trace.iw+x-trace.tx]),'retained source');
 }};
 check(0,'circle clip input');
 const opening=runtime.layoutReport(0,4).objects;
 assert(opening.some(o=>o.id==='circle_clip'&&o.visible));
 assert(!opening.some(o=>o.id==='rect_clip'||o.id==='state_1'||o.id==='state_2'));
 const data=trace.cases[2];assert.equal(trace.cases[0].clipTasks,0);assert.equal(trace.cases[1].clipTasks,0);assert.equal(trace.cases[1].fastTrack,true);assert.equal(data.clipTasks,1);
 assert.notDeepEqual(data.clipRle,data.imageRle);
 assert(data.clipRle.some(c=>!data.rawRle.some(r=>r.y===c.y)));
 let t=.5+.15+.15;
 memory.fill(trace.background);check(t,'circle Prepare leaves destination blank');
 const clipDone=t+data.clipRle.length*.035;
 const ready=runtime.layoutReport(clipDone+.25,4).objects;
 assert(ready.some(o=>o.id==='label_done'&&o.visible));assert(!ready.some(o=>o.id?.startsWith('raw_span_')&&o.visible));
 t=clipDone+.2+.4+data.rawRle.length*.10+.4;
 const rawReady=runtime.layoutReport(t-.02,4).objects;assert(!rawReady.some(o=>o.id?.startsWith('final_span_')&&o.visible));check(t-.02,'raw image RLE still does not draw');
 const samples=[0,clipDone+.25,t-.02];
 for(let y=0;y<trace.h;y++) {t+=.08+.20+.25+.08;check(t,`intersection row ${y}: no drawing`);}
 const previewTime=t;
 t+=.15+.12+.12+.65+.15+.6+.12+.15;
 check(t,'image.rle replaced: Surface still blank');
 const settled=runtime.layoutReport(t,4).objects;
 assert(!settled.some(o=>o.id?.startsWith('raw_span_')&&o.visible));
 for(let i=0;i<data.imageRle.length;i++){
  const s=data.imageRle[i];assert(data.rawRle.some(r=>r.y===s.y&&r.x<=s.x&&r.x+r.len>=s.x+s.len&&r.coverage===255));
  t+=.06+.04;
  const moving=Buffer.from(runtime.render(t+.11,true));
  for(let j=0;j<s.len;j++)eq(pixel(moving,width,900+(s.x+j+.5)*44+385,220+(s.y+.5)*44),rgb(trace.source[(s.y-trace.ty)*trace.iw+s.x+j-trace.tx]),'moving source color copy');
  t+=.22+.12+.06;data.writes[i].forEach((v,j)=>memory[s.y*trace.stride+s.x+j]=v);check(t+.02,`clipped span ${i}`);
  t+=(s.len>=4?.3:.06)+.06;
 }
 assert.deepEqual(memory,data.pixels);assert(Math.abs(duration-(t+3))<.002);check(duration,'final');samples.push(previewTime,duration);
 for(const [prefix,base,spans,time] of [['clip',130,data.clipRle,duration],['raw',900,data.rawRle,previewTime],['final',900,data.imageRle,duration]])for(const [i,s] of spans.entries()){
  const key=`${prefix}_span_${i+1}`,b=runtime.bounds(key+'_begin',time);
  assert(Math.abs(b.x+b.width/2-(base+(s.x+.5)*44))<1);
  const objects=runtime.layoutReport(time,4).objects;
  if(s.len===1){assert(!objects.some(o=>o.id===key+'_len'||o.id===key+'_end'));}
  else{const l=runtime.bounds(key+'_len',time);assert(Math.abs(l.width-(s.len-1)*44)<3);assert(Math.abs(l.x+l.width/2-(base+(s.x+s.len/2)*44))<1);}
  const rendered=Buffer.from(runtime.render(time,true)),shade=255-Math.floor(s.coverage*195/255);
  eq(pixel(rendered,width,base+(s.x+.25)*44,840+(s.y+.25)*44),[shade,shade,shade],'span coverage shade');
 }
 runtime.loadLua(source.replace('local trace='+lua(trace),'local trace='+lua(variant)),'clip-variant.lua');const changed=Buffer.from(runtime.render(runtime.duration,true));let differences=0;
 for(let y=0;y<variant.h;y++)for(let x=0;x<variant.w;x++){const at=y*variant.stride+x;eq(pixel(changed,width,1670+(x+.5)*44,220+(y+.5)*44),rgb(variant.cases[2].pixels[at]),'independent clip variant');if(variant.cases[2].pixels[at]!==data.pixels[at])differences++;}assert(differences>10);
 runtime.loadLua(source,'sw-image-clip-tasks.lua');
 const report={width,height,duration,frames,framesAudited:frames,labels:labels.size,minMargin:margin,pixelChecks:checks,clipSpans:data.clipRle.length,rawSpans:data.rawRle.length,finalSpans:data.imageRle.length,variantDifferences:differences};console.log(JSON.stringify(report));await fs.writeFile(path.join(temp,'review.txt'),JSON.stringify(report,null,2)+'\n');
 for(const [i,time] of samples.entries())await sharp(Buffer.from(runtime.render(time,true)),{raw:{width,height,channels:4}}).png().toFile(path.join(temp,'review-'+i+'.png'));
 await sharp(Buffer.from(runtime.render(duration,true)),{raw:{width,height,channels:4}}).webp({lossless:true}).toFile(path.join(out,'image-clip-tasks.webp'));
 if(!process.argv.includes('--preview') && process.argv.includes('--video')){
  const ff=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','rgba','-video_size',`${width}x${height}`,'-framerate','30','-i','pipe:0','-an','-c:v','libx264','-preset','medium','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',path.join(out,'image-clip-tasks.mp4')],{stdio:['pipe','inherit','inherit']});const end=once(ff,'close');for(let f=0;f<frames;f++){if(!ff.stdin.write(Buffer.from(runtime.render(Math.min(f/30,duration),true))))await once(ff.stdin,'drain');if(f%180===0)console.log(`${f}/${frames}`);}ff.stdin.end();const [code]=await end;assert.equal(code,0);
 }
}finally{runtime.destroy();}
